func (c *Core) dxOpenAndFillInternal(inHigh, inLow, inClose []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outReal []float64) (*DXStream, error) {
	sp := &DXStream{core: c}
	if retCode := c.dxOpenImpl(sp, inHigh, inLow, inClose, startIdx, optInTimePeriod, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) dxOpenInternal(inHigh, inLow, inClose []float64, startIdx, optInTimePeriod int32) (*DXStream, error) {
	sp := &DXStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.dxOpenImpl(sp, inHigh, inLow, inClose, startIdx, optInTimePeriod, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// DXOpen opens a live [DXStream] on a warm-up history, oldest bar first, and
// returns it with its value at the last history bar, the value [Core.DX] writes
// there.
//
// inHigh, inLow and inClose are the histories, of one length; the parameters
// are those of [Core.DX].
//
// The error is [InsufficientHistory] for a history of at most [Core.DXLookback]
// bars, and [BadParam] for a parameter out of range or histories of different
// lengths.
func (c *Core) DXOpen(inHigh, inLow, inClose []float64, optInTimePeriod int) (*DXStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.dxOpenInternal(inHigh, inLow, inClose, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// DXOpenAndFill opens a stream as [Core.DXOpen] does and also writes the
// outputs over the whole history, as [Core.DX] writes them for bars 0 through
// len(inHigh)-1, returning that range.
//
// Each output must hold len(inHigh) minus [Core.DXLookback] values and share no
// memory with an input or another output.
//
// The errors are those of [Core.DXOpen], and [BadParam] for an output that is
// empty, too short or sharing memory.
func (c *Core) DXOpenAndFill(inHigh, inLow, inClose []float64, optInTimePeriod int, outReal []float64) (*DXStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.dxLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inHigh) || sameStart(outReal, inLow) || sameStart(outReal, inClose) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inHigh) || overlaps(outReal, inLow) || overlaps(outReal, inClose)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.dxOpenAndFillInternal(inHigh, inLow, inClose, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
